// ---- _shared/token.ts
// Signed counter QR tokens and staff PIN hashes.
// Uses only WebCrypto, available in Deno (Edge Functions) and Node 20+ (admin script, tests).
// The secrets never reach the app: the app only scans and forwards the payload.

/** Scheme printed in the counter QR. Opening it with any camera app deep-links into Perko. */
const QR_PREFIX = 'perko://c/';

const enc = new TextEncoder();

function b64url(bytes: Uint8Array): string {
  let s = '';
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

async function hmac(secret: string, message: string): Promise<Uint8Array> {
  const key = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return new Uint8Array(await crypto.subtle.sign('HMAC', key, enc.encode(message)));
}

/** Constant-time string comparison. */
function safeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

async function qrSignature(secret: string, version: number, qrId: string): Promise<string> {
  // 16 bytes of the HMAC (128 bits) keep the printed code small and are plenty against guessing.
  return b64url((await hmac(secret, `perko.qr.v${version}.${qrId.toLowerCase()}`)).slice(0, 16));
}

/** Build the payload printed on a business's counter code. */
async function signQrPayload(secret: string, version: number, qrId: string): Promise<string> {
  if (!UUID.test(qrId)) throw new Error('qrId must be a uuid');
  return `${QR_PREFIX}v${version}.${qrId.toLowerCase()}.${await qrSignature(secret, version, qrId)}`;
}

type ParsedQr = { version: number; qrId: string; signature: string };

/** Parse without verifying. Returns null for anything that is not a Perko counter code. */
function parseQrPayload(payload: string): ParsedQr | null {
  const raw = payload.trim();
  if (!raw.startsWith(QR_PREFIX)) return null;
  const m = /^v(\d{1,3})\.([0-9a-f-]{36})\.([A-Za-z0-9_-]{22})$/.exec(raw.slice(QR_PREFIX.length));
  if (!m || !UUID.test(m[2])) return null;
  return { version: Number(m[1]), qrId: m[2].toLowerCase(), signature: m[3] };
}

/**
 * Verify a scanned payload. `secrets` maps key version to secret so codes can be rotated:
 * print new codes with a new version, keep the old secret until the old codes are collected, then drop it.
 */
async function verifyQrPayload(payload: string, secrets: Record<number, string>): Promise<ParsedQr | null> {
  const parsed = parseQrPayload(payload);
  if (!parsed) return null;
  const secret = secrets[parsed.version];
  if (!secret) return null;
  const expected = await qrSignature(secret, parsed.version, parsed.qrId);
  return safeEqual(expected, parsed.signature) ? parsed : null;
}

/** Staff PINs are 4 digits, typed by a staff member on the customer's phone. */
const PIN_LENGTH = 4;

function isPinFormat(pin: unknown): pin is string {
  return typeof pin === 'string' && /^\d{4}$/.test(pin);
}

function hex(bytes: Uint8Array): string {
  let s = '';
  for (const b of bytes) s += b.toString(16).padStart(2, '0');
  return s;
}

/**
 * What the database stores for a staff PIN: HMAC-SHA256 keyed with PIN_SECRET over the business id and the PIN.
 * Without the secret a leaked table cannot be brute-forced (10,000 PINs would take a moment with a plain hash).
 * The business id makes the same PIN in two businesses look unrelated.
 */
async function hashPin(secret: string, businessId: string, pin: string): Promise<string> {
  if (!isPinFormat(pin)) throw new Error('a PIN is 4 digits');
  return hex(await hmac(secret, `perko.pin.${businessId.toLowerCase()}.${pin}`));
}

/** PINs a guesser tries first: one digit repeated (0000) and runs (1234, 9876). */
function isWeakPin(pin: string): boolean {
  if (/^(\d)\1{3}$/.test(pin)) return true;
  const d = [...pin].map(Number);
  const steps = d.slice(1).map((x, i) => x - d[i]);
  return steps.every((s) => s === 1) || steps.every((s) => s === -1);
}

/** A random PIN, never a weak one. Uses WebCrypto, so it is unpredictable. */
function randomPin(): string {
  for (;;) {
    const n = crypto.getRandomValues(new Uint32Array(1))[0];
    // 4,294,960,000 is a multiple of 10,000: dropping the top few values keeps every PIN equally likely.
    if (n >= 4_294_960_000) continue;
    const pin = String(n % 10_000).padStart(PIN_LENGTH, '0');
    if (!isWeakPin(pin)) return pin;
  }
}

// ---- _shared/sun.ts
// NTAG 424 DNA Secure Unique NFC (SUN) messages: verification of a tap, per NXP AN12196 ("NTAG 424 DNA and
// NTAG 424 DNA TagTamper features and hints") and the NT4H2421Gx datasheet.
//
// Every tap makes the tag write a fresh URL: https://www.getperko.com/t?p=<PICCData>&c=<SUN MAC>
//   p  32 hex: AES-128-CBC(SDMMetaReadKey, IV 0) of PICCDataTag || UID (7) || SDMReadCtr (3, LSB first) || pad
//   c  16 hex: the odd bytes of AES-CMAC(KSesSDMFileReadMAC, empty input)
//      KSesSDMFileReadMAC = AES-CMAC(SDMFileReadKey, 3C C3 00 01 00 80 || UID || SDMReadCtr)
// Keys: SDMMetaReadKey is one key for every Perko tag (secret NFC_META_KEY); SDMFileReadKey is per tag,
// AES-CMAC(NFC_MASTER_KEY, UID), so no per-tag key is stored. Keys only ever live in Edge Function secrets
// (and the operator's .env for scripts/admin.ts). Never log keys, p, c or the full URL.
//
// WebCrypto only (Deno and Node 20+), no imports. WebCrypto has no raw AES block mode, so one block is
// encrypted with AES-CBC (zero IV) and the padding block dropped, and decrypted with a crafted padding block.

type SunTap = { uid: string; counter: number };

const ZERO_IV = new Uint8Array(16);

function fromHex(hex: string): Uint8Array {
  if (!/^(?:[0-9a-fA-F]{2})*$/.test(hex)) throw new Error('not hex');
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  return out;
}

function toHex(bytes: Uint8Array): string {
  let s = '';
  for (const b of bytes) s += b.toString(16).padStart(2, '0');
  return s.toUpperCase();
}

function xor(a: Uint8Array, b: Uint8Array): Uint8Array {
  const out = new Uint8Array(a.length);
  for (let i = 0; i < a.length; i++) out[i] = a[i] ^ b[i];
  return out;
}

/** A copy backed by a plain ArrayBuffer, as WebCrypto's types want. */
const own = (u: Uint8Array): Uint8Array<ArrayBuffer> => new Uint8Array(u);

async function cbcKey(key: Uint8Array, usage: 'encrypt' | 'decrypt'): Promise<CryptoKey> {
  if (key.length !== 16) throw new Error('AES-128 key must be 16 bytes');
  return crypto.subtle.importKey('raw', own(key), { name: 'AES-CBC' }, false, [usage]);
}

/** AES-128 of one 16-byte block (ECB). */
async function aesEncryptBlock(key: Uint8Array, block: Uint8Array): Promise<Uint8Array> {
  const out = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-CBC', iv: ZERO_IV }, await cbcKey(key, 'encrypt'), own(block)));
  return out.slice(0, 16);
}

/** AES-128 decryption of one 16-byte block (ECB). Appends a block that decrypts to valid PKCS#7 padding. */
async function aesDecryptBlock(key: Uint8Array, block: Uint8Array): Promise<Uint8Array> {
  const pad = await aesEncryptBlock(key, xor(new Uint8Array(16).fill(16), block));
  const both = new Uint8Array(32);
  both.set(block, 0);
  both.set(pad, 16);
  const out = new Uint8Array(await crypto.subtle.decrypt({ name: 'AES-CBC', iv: ZERO_IV }, await cbcKey(key, 'decrypt'), both));
  return out.slice(0, 16);
}

function shiftLeft(b: Uint8Array): Uint8Array {
  const out = new Uint8Array(16);
  for (let i = 0; i < 16; i++) out[i] = ((b[i] << 1) & 0xff) | (i < 15 ? b[i + 1] >> 7 : 0);
  return out;
}

/** AES-CMAC (NIST SP 800-38B, RFC 4493) with a 128-bit key. */
async function aesCmac(key: Uint8Array, message: Uint8Array): Promise<Uint8Array> {
  const l = await aesEncryptBlock(key, new Uint8Array(16));
  const k1 = shiftLeft(l);
  if (l[0] & 0x80) k1[15] ^= 0x87;
  const k2 = shiftLeft(k1);
  if (k1[0] & 0x80) k2[15] ^= 0x87;

  const n = Math.max(1, Math.ceil(message.length / 16));
  const complete = message.length > 0 && message.length % 16 === 0;
  const last = new Uint8Array(16);
  const tail = message.slice((n - 1) * 16);
  last.set(tail);
  if (!complete) last[tail.length] = 0x80;
  const lastBlock = xor(last, complete ? k1 : k2);

  let x: Uint8Array = new Uint8Array(16);
  for (let i = 0; i < n - 1; i++) x = await aesEncryptBlock(key, xor(x, message.slice(i * 16, i * 16 + 16)));
  return aesEncryptBlock(key, xor(x, lastBlock));
}

/** The 8 bytes of a SUN MAC: bytes 1, 3, 5, ..., 15 of the full CMAC. */
function truncateMac(full: Uint8Array): Uint8Array {
  const out = new Uint8Array(8);
  for (let i = 0; i < 8; i++) out[i] = full[i * 2 + 1];
  return out;
}

/** A tag's SDMFileReadKey: AES-CMAC(master, UID). Also what the operator writes to the tag as key 2. */
async function fileReadKey(master: Uint8Array, uid: Uint8Array): Promise<Uint8Array> {
  return aesCmac(master, uid);
}

/** A tag's application master key (key 0), so nobody can reconfigure a provisioned tag. Never used to verify. */
async function appMasterKey(master: Uint8Array, uid: Uint8Array): Promise<Uint8Array> {
  const msg = new Uint8Array(uid.length + 1);
  msg[0] = 0x00;
  msg.set(uid, 1);
  return aesCmac(master, msg);
}

/** Decrypts p: the UID and read counter, or null when it is not Perko PICC data (tag byte 0xC7: UID + counter). */
async function decryptPicc(metaKey: Uint8Array, p: Uint8Array): Promise<{ uid: Uint8Array; ctr: Uint8Array } | null> {
  if (p.length !== 16) return null;
  const plain = await aesDecryptBlock(metaKey, p);
  // PICCDataTag: bit 7 UID mirrored, bit 6 counter mirrored, low nibble UID length (7).
  if (plain[0] !== 0xc7) return null;
  return { uid: plain.slice(1, 8), ctr: plain.slice(8, 11) };
}

/** The SUN MAC for a UID and counter, with the tag's file-read key. */
async function sunMac(fileKey: Uint8Array, uid: Uint8Array, ctr: Uint8Array): Promise<Uint8Array> {
  const sv2 = new Uint8Array(16);
  sv2.set([0x3c, 0xc3, 0x00, 0x01, 0x00, 0x80], 0);
  sv2.set(uid, 6);
  sv2.set(ctr, 13);
  const session = await aesCmac(fileKey, sv2);
  return truncateMac(await aesCmac(session, new Uint8Array(0)));
}

function sameBytes(a: Uint8Array, b: Uint8Array): boolean {
  if (a.length !== b.length) return false;
  let d = 0;
  for (let i = 0; i < a.length; i++) d |= a[i] ^ b[i];
  return d === 0;
}

/**
 * Verifies a tap. Returns the tag's UID (14 upper-case hex) and read counter, or null when p or c is malformed,
 * was not made by a Perko tag, or was altered. The caller still has to check the counter against the last one.
 */
async function verifySun(
  keys: { meta: Uint8Array; master: Uint8Array },
  p: string,
  c: string,
): Promise<SunTap | null> {
  if (!/^[0-9a-fA-F]{32}$/.test(p) || !/^[0-9a-fA-F]{16}$/.test(c)) return null;
  const picc = await decryptPicc(keys.meta, fromHex(p));
  if (!picc) return null;
  const mac = await sunMac(await fileReadKey(keys.master, picc.uid), picc.uid, picc.ctr);
  if (!sameBytes(mac, fromHex(c))) return null;
  return { uid: toHex(picc.uid), counter: picc.ctr[0] | (picc.ctr[1] << 8) | (picc.ctr[2] << 16) };
}

/** The tap's p and c from the tag URL, the perko://t link or the bare query. Format only, nothing verified. */
function parseNfcPayload(input: string): { p: string; c: string } | null {
  const s = input.trim();
  if (s.length > 300) return null;
  const query = s.includes('?') ? s.slice(s.indexOf('?') + 1) : s;
  const params = new Map<string, string>();
  for (const part of query.split('&')) {
    const i = part.indexOf('=');
    if (i > 0) params.set(part.slice(0, i), part.slice(i + 1));
  }
  const p = params.get('p') ?? '';
  const c = params.get('c') ?? '';
  if (!/^[0-9a-fA-F]{32}$/.test(p) || !/^[0-9a-fA-F]{16}$/.test(c)) return null;
  if (s.includes('?') && !/^(https:\/\/(www\.)?getperko\.com\/t|perko:\/\/t)\/?\?/.test(s)) return null;
  return { p: p.toUpperCase(), c: c.toUpperCase() };
}

/** The payload the app sends to collect for a tap. */
function nfcPayload(p: string, c: string): string {
  return `p=${p}&c=${c}`;
}

/** The URL the tag writes, with SDM placeholders where the tag mirrors p (32 chars) and c (16 chars). */
const NFC_URL_TEMPLATE = 'https://www.getperko.com/t?p=00000000000000000000000000000000&c=0000000000000000';

/** Hex secrets of 16 bytes (NFC_META_KEY, NFC_MASTER_KEY). */
function keyFromHex(hex: string | undefined): Uint8Array | null {
  return hex && /^[0-9a-fA-F]{32}$/.test(hex) ? fromHex(hex) : null;
}

// ---- _shared/api-types.ts
// Request and response shapes of the Edge Functions, shared with the app. No imports.


/** Where a collection came from: the counter QR code, or a tap on the business's NTAG 424 DNA tag. */
type CollectSource = 'qr' | 'nfc';

/**
 * QR: two calls. 'check' (no PIN) runs every test that does not need the staff member: the code, the lockout,
 * the rate limit and the cooldown, so the customer learns "come back later" before anyone types a PIN.
 * 'collect' repeats them with the 4-digit staff PIN and writes the stamp.
 * NFC: payload is "p=<32 hex>&c=<16 hex>" from the tap. 'collect' without a PIN writes the stamp, unless the
 * business requires a PIN for NFC too: then it answers 'pin_required' (nothing written, the tap not used) and
 * the app sends the same tap again with the PIN.
 */
type CollectRequest = { payload: string; source: CollectSource; action: 'check' | 'collect'; pin?: string };

type CollectedCard = {
  cardId: string;
  businessId: string;
  businessName: string;
  programName: string;
  type: ProgramType;
  goal: number;
  current: number;
  reward: string;
};

/** What the customer will get, shown above the PIN pad. The card may not exist yet (first scan). */
type PendingCollect = Omit<CollectedCard, 'cardId'> & { cardId: string | null; step: number };

type CollectResponse =
  // confirmation: when this scan filled the card, the id of the stamp it wrote. Sent back to redeem ('fill')
  // within 2 minutes, it confirms the reward without a second PIN.
  | ({ status: 'ok'; added: number; completed: boolean; confirmation?: string } & CollectedCard)
  | { status: 'cooldown'; retryAt: string; remainingMinutes: number; businessName: string }
  | ({ status: 'complete' } & CollectedCard) // the card is already full: redeem first
  | ({ status: 'pin_required' } & PendingCollect) // check passed: show the PIN pad to the staff member
  | { status: 'wrong_pin'; attemptsLeft: number; businessName: string }
  | { status: 'locked'; until: string; businessName: string } // too many wrong PINs today at this business
  | { status: 'invalid' } // not a Perko code, bad signature, unknown code
  | { status: 'inactive' } // revoked code, or the business or program is paused
  | { status: 'rate_limited' }
  | { status: 'nfc_replayed' }; // a tap that was already used (a saved link): tap the tag again

/**
 * A reward is used when a staff member types their PIN on the customer's phone ('confirm'), or right after the
 * scan that filled the card, with that scan's confirmation ('fill'): checked on the server, same card, 2 minutes.
 */
type RedeemRequest =
  | { action: 'confirm'; cardId: string; pin: string }
  | { action: 'fill'; cardId: string; confirmation: string };

type RedeemResponse =
  | { status: 'redeemed'; newCardId: string; reward: string }
  | { status: 'wrong_pin'; attemptsLeft: number }
  | { status: 'locked'; until: string } // too many wrong PINs today at this business
  | { status: 'not_ready' } // the card is not complete (or already redeemed)
  | { status: 'not_found' }
  | { status: 'confirmation_invalid' }; // 'fill' only: another card, too old or already used. Confirm with a PIN.

// business-admin: what the owner dashboard (and scripts/admin.ts with the service role key) can do.
type PinMode = 'shared' | 'per_staff';

type BusinessAdminRequest =
  | { action: 'pin_mode'; businessId: string; mode: PinMode } // switching to shared creates the team PIN
  | { action: 'team_pin'; businessId: string } // create or replace the team PIN (shared mode)
  | { action: 'staff_add'; businessId: string; name: string } // per_staff mode
  | { action: 'staff_remove'; businessId: string; staffPinId: string }
  | { action: 'pin_reset'; businessId: string; staffPinId: string }
  | { action: 'qr_list'; businessId: string }
  | { action: 'qr_create'; businessId: string; label?: string }
  | { action: 'lockout_release'; businessId: string; alertId: string }; // clears today's PIN lockout behind the alert

type CounterCode = { id: string; label: string | null; payload: string; createdAt: string };

type BusinessAdminResponse =
  | { status: 'ok' }
  | { status: 'pin'; staffPinId: string; name: string; pin: string } // the PIN is shown once, never stored in clear
  | { status: 'qr'; businessName: string; codes: CounterCode[] }
  | { status: 'forbidden' }
  | { status: 'invalid'; message: string };

// ---- _shared/server.ts
// Helpers for the Edge Functions (Deno). Not imported by the app.

const cors = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...cors, 'Content-Type': 'application/json' } });
}

/** Service-role client: bypasses RLS, so every query below must filter by the verified user id. */
function admin(): SupabaseClient {
  return createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
}

/** The signed-in user, from the Authorization header. */
async function requireUser(req: Request, db: SupabaseClient): Promise<{ id: string } | null> {
  const token = (req.headers.get('Authorization') ?? '').replace(/^Bearer\s+/i, '');
  if (!token) return null;
  const { data, error } = await db.auth.getUser(token);
  if (error || !data.user) return null;
  return { id: data.user.id };
}

/** QR secrets by key version, from QR_SECRET_V1, QR_SECRET_V2, ... */
function qrSecrets(): Record<number, string> {
  const out: Record<number, string> = {};
  for (const [k, v] of Object.entries(Deno.env.toObject())) {
    const m = /^QR_SECRET_V(\d+)$/.exec(k);
    if (m && v) out[Number(m[1])] = v;
  }
  return out;
}

function secret(name: string): string {
  const v = Deno.env.get(name);
  if (!v) throw new Error(`missing secret ${name}`);
  return v;
}

/** The `role` claim of a JWT, without checking its signature. */
function jwtRole(token: string): string | null {
  try {
    const part = token.split('.')[1].replace(/-/g, '+').replace(/_/g, '/');
    return JSON.parse(atob(part.padEnd(part.length + ((4 - (part.length % 4)) % 4), '='))).role ?? null;
  } catch {
    return null;
  }
}

/**
 * The caller of an owner action: a signed-in user, or the pilot admin script, which sends the service role key
 * itself (scripts/admin.ts pins:set, for businesses that have no owner yet).
 * Only for functions deployed with verify_jwt on (business-admin): the gateway has then already verified the
 * token's signature, so its role claim can be trusted. The key the function sees in SUPABASE_SERVICE_ROLE_KEY is
 * not always the same string as the dashboard's legacy service_role key, so the claim is what identifies it.
 */
async function requireCaller(req: Request, db: SupabaseClient): Promise<{ service: true } | { service: false; id: string } | null> {
  const token = (req.headers.get('Authorization') ?? '').replace(/^Bearer\s+/i, '');
  if (token && jwtRole(token) === 'service_role') return { service: true };
  const user = await requireUser(req, db);
  return user ? { service: false, id: user.id } : null;
}

// ---- _shared/pins.ts
// Staff PINs on the server (Deno): checking a PIN typed at the counter and issuing new ones.
// The PIN itself is never stored, only hashPin() of it, keyed with PIN_SECRET.

type PinCheck =
  | { kind: 'ok'; staffPinId: string }
  | { kind: 'wrong'; attemptsLeft: number }
  | { kind: 'locked'; until: string };

/** Midnight in Israel when the customer is locked out at this business, else null. */
async function lockedUntil(db: SupabaseClient, userId: string, businessId: string): Promise<string | null> {
  const { data, error } = await db.rpc('pin_locked_until', { p_user: userId, p_business: businessId });
  if (error) throw new Error(`pin_locked_until: ${error.message}`);
  return (data as string | null) ?? null;
}

/**
 * Checks a PIN typed at the counter against the business's active PINs. A wrong PIN is logged; the last
 * allowed one locks the customer at this business until midnight and alerts the owner (register_pin_failure).
 * Call lockedUntil() first: a locked customer must not get another try.
 */
async function checkStaffPin(
  db: SupabaseClient, secret: string, userId: string, businessId: string, pin: unknown, context: 'collect' | 'redeem',
): Promise<PinCheck> {
  if (isPinFormat(pin)) {
    const { data } = await db
      .from('staff_pins')
      .select('id')
      .eq('business_id', businessId)
      .eq('pin_hash', await hashPin(secret, businessId, pin))
      .eq('active', true)
      .maybeSingle();
    if (data) return { kind: 'ok', staffPinId: data.id };
  }
  const { data: failures, error } = await db.rpc('register_pin_failure', { p_user: userId, p_business: businessId, p_context: context });
  if (error) throw new Error(`register_pin_failure: ${error.message}`);
  const n = Number(failures);
  if (n >= PIN_MAX_FAILURES) {
    return { kind: 'locked', until: (await lockedUntil(db, userId, businessId)) ?? new Date().toISOString() };
  }
  return { kind: 'wrong', attemptsLeft: PIN_MAX_FAILURES - n };
}

/** Creates an active PIN for a staff member (or "צוות") and returns it. It is shown once and never again. */
async function issuePin(db: SupabaseClient, secret: string, businessId: string, name: string): Promise<{ id: string; pin: string }> {
  // A PIN must be unique among the business's active PINs; with at most a few dozen staff a clash is rare.
  for (let i = 0; i < 25; i++) {
    const pin = randomPin();
    const { data, error } = await db
      .from('staff_pins')
      .insert({ business_id: businessId, name, pin_hash: await hashPin(secret, businessId, pin) })
      .select('id')
      .single();
    if (data) return { id: data.id, pin };
    if (error?.code !== '23505') throw new Error(`staff_pins: ${error?.message}`);
  }
  throw new Error('could not find a free PIN');
}

// ---- collect/index.ts
// POST /functions/v1/collect
//   { payload, source: 'qr', action: 'check' }               -> may the customer collect now? (no PIN, no write)
//   { payload, source: 'qr', action: 'collect', pin: '1234' } -> the staff member confirmed: write the stamp
//   { payload: 'p=..&c=..', source: 'nfc', action: 'collect', pin? } -> a tap on the business's NFC tag
// The only way a stamp or points are added. Verifies the signed counter code or the tag's SUN message, the
// customer's PIN lockout at the business, the per-user rate limit and the cooldown, then the staff PIN when one
// is needed, and writes atomically via apply_collect() / apply_nfc_collect(). The counter QR alone is not
// enough: it is printed and can be photographed, so it always needs the PIN. A tap cannot be copied (the tag's
// counter must grow) and the tag stays with the staff, so it needs the PIN only if the business asks for it.

const CARD_COLUMNS = 'id, current, status, version, last_collected_at, type, goal, step, reward';

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: cors });
  if (req.method !== 'POST') return json({ error: 'method' }, 405);

  const db = admin();
  const user = await requireUser(req, db);
  if (!user) return json({ error: 'unauthorized' }, 401);

  let body: CollectRequest;
  try {
    body = await req.json();
  } catch {
    return json({ status: 'invalid' } satisfies CollectResponse);
  }
  if ((body.source !== 'qr' && body.source !== 'nfc') || typeof body.payload !== 'string' || body.payload.length > 200) {
    return json({ status: 'invalid' } satisfies CollectResponse);
  }
  const writing = body.action !== 'check';

  // 1-2. Where the stamp comes from: the signed counter QR, or the tag's SUN message. Either way the business,
  //      checked active. Nothing here logs the payload: it is a credential while it is fresh.
  type Biz = { id: string; name: string; active: boolean; nfc_require_pin: boolean };
  let business: Biz | null;
  let qrId: string | null = null;
  let tap: { tagId: string; counter: number } | null = null;
  if (body.source === 'qr') {
    // A code that does not verify is "invalid" whatever it contains.
    const parsed = await verifyQrPayload(body.payload, qrSecrets());
    if (!parsed) return json({ status: 'invalid' } satisfies CollectResponse);
    const { data: qr } = await db
      .from('qr_codes')
      .select('id, active, key_version, business:businesses(id, name, active, nfc_require_pin)')
      .eq('id', parsed.qrId)
      .maybeSingle();
    if (!qr || qr.key_version !== parsed.version) return json({ status: 'invalid' } satisfies CollectResponse);
    business = qr.business as unknown as Biz | null;
    if (!qr.active || !business?.active) return json({ status: 'inactive' } satisfies CollectResponse);
    qrId = qr.id;
  } else {
    const nfc = parseNfcPayload(body.payload);
    const meta = keyFromHex(Deno.env.get('NFC_META_KEY'));
    const master = keyFromHex(Deno.env.get('NFC_MASTER_KEY'));
    if (!meta || !master) return json({ error: 'nfc not configured' }, 500);
    // A tap that was not made by a Perko tag, or was altered: "invalid" whatever it contains.
    const sun = nfc ? await verifySun({ meta, master }, nfc.p, nfc.c) : null;
    if (!sun) return json({ status: 'invalid' } satisfies CollectResponse);
    const { data: tag } = await db
      .from('nfc_tags')
      .select('id, active, last_counter, business:businesses(id, name, active, nfc_require_pin)')
      .eq('uid', sun.uid)
      .maybeSingle();
    if (!tag) return json({ status: 'invalid' } satisfies CollectResponse);
    business = tag.business as unknown as Biz | null;
    if (!tag.active) {
      await db.rpc('register_nfc_rejection', { p_tag_id: tag.id, p_user: user.id, p_counter: sun.counter, p_reason: 'inactive' });
      return json({ status: 'inactive' } satisfies CollectResponse);
    }
    if (!business?.active) return json({ status: 'inactive' } satisfies CollectResponse);
    // The tag's counter only grows: an old one is a saved or copied link. Checked again when writing.
    if (sun.counter <= tag.last_counter) {
      await db.rpc('register_nfc_rejection', { p_tag_id: tag.id, p_user: user.id, p_counter: sun.counter, p_reason: 'stale' });
      return json({ status: 'nfc_replayed' } satisfies CollectResponse);
    }
    tap = { tagId: tag.id, counter: sun.counter };
  }
  const needPin = pinRequired(body.source, business.nfc_require_pin);

  const { data: program } = await db
    .from('programs')
    .select('id, name, type, goal, step, reward, cooldown_minutes')
    .eq('business_id', business.id)
    .eq('active', true)
    .maybeSingle();
  if (!program) return json({ status: 'inactive' } satisfies CollectResponse);

  // 3. Too many wrong PINs today at this business: no more tries until midnight.
  const until = await lockedUntil(db, user.id, business.id);
  if (until) return json({ status: 'locked', until, businessName: business.name } satisfies CollectResponse);

  // 4. Per-user rate limit across all businesses.
  const longest = Math.max(...RATE_LIMITS.map((l) => l.windowMinutes));
  const { data: recent } = await db
    .from('stamp_events')
    .select('created_at')
    .eq('user_id', user.id)
    .gte('created_at', new Date(Date.now() - longest * 60_000).toISOString());
  if (isRateLimited((recent ?? []).map((r) => r.created_at), new Date())) {
    return json({ status: 'rate_limited' } satisfies CollectResponse, 429);
  }

  // 5. The user's open card on this program. It keeps the rules it was opened with; before the first stamp
  //    there is no card yet and the program's current rules apply (the card will copy them).
  const { data: card } = await db
    .from('cards')
    .select(CARD_COLUMNS)
    .eq('user_id', user.id)
    .eq('program_id', program.id)
    .neq('status', 'redeemed')
    .maybeSingle();
  const terms = card ?? { type: program.type, goal: program.goal, step: program.step, reward: program.reward };

  // The cooldown is per user and business, not per card: a fresh card right after a redemption
  // does not reopen the slot that the completing scan used. It is read live from the program.
  const { data: lastEvent } = await db
    .from('stamp_events')
    .select('created_at')
    .eq('user_id', user.id)
    .eq('business_id', business.id)
    .order('created_at', { ascending: false })
    .limit(1)
    .maybeSingle();
  const lastCollectedAt = [card?.last_collected_at, lastEvent?.created_at].filter(Boolean).sort().pop() ?? null;

  const rules = { type: terms.type, goal: terms.goal, step: terms.step, cooldownMinutes: program.cooldown_minutes };
  const pending = {
    businessId: business.id,
    businessName: business.name,
    programName: program.name,
    type: terms.type,
    goal: terms.goal,
    step: terms.step,
    current: card?.current ?? 0,
    reward: terms.reward,
  };

  // 6. Decide (pure, unit-tested). Cooldown and a full card are answered before anyone types a PIN.
  const now = new Date();
  const decision = decideCollect(rules, { current: card?.current ?? 0, status: card?.status ?? 'active', lastCollectedAt }, now);
  if (decision.kind === 'cooldown') {
    return json({ status: 'cooldown', retryAt: decision.retryAt, remainingMinutes: decision.remainingMinutes, businessName: business.name } satisfies CollectResponse);
  }
  if (decision.kind !== 'apply') {
    return json({ status: 'complete', ...pending, cardId: card!.id } satisfies CollectResponse);
  }
  // No PIN yet where one is needed: show the PIN pad. Nothing is written and an NFC tap is not used up.
  // (The app sends an NFC tap straight as 'collect'; 'check' is the QR's first step.)
  if (!writing || (needPin && body.pin === undefined)) {
    return json({ status: 'pin_required', ...pending, cardId: card?.id ?? null } satisfies CollectResponse);
  }

  // 7. The staff PIN, when needed. A wrong one is logged and counts towards the lockout.
  let staffPinId: string | null = null;
  if (needPin) {
    const pin = await checkStaffPin(db, secret('PIN_SECRET'), user.id, business.id, body.pin, 'collect');
    if (pin.kind === 'locked') return json({ status: 'locked', until: pin.until, businessName: business.name } satisfies CollectResponse);
    if (pin.kind === 'wrong') return json({ status: 'wrong_pin', attemptsLeft: pin.attemptsLeft, businessName: business.name } satisfies CollectResponse);
    staffPinId = pin.staffPinId;
  }

  // 8. The first stamp adds the card to the wallet.
  let open = card;
  if (!open) {
    const ins = await db.from('cards').insert({ user_id: user.id, program_id: program.id }).select(CARD_COLUMNS).single();
    // A parallel request may have created it first: read it again.
    open = ins.data ?? (await db.from('cards').select(CARD_COLUMNS)
      .eq('user_id', user.id).eq('program_id', program.id).neq('status', 'redeemed').single()).data;
  }
  if (!open) return json({ error: 'card' }, 500);
  // A card created in between (another device) may already hold stamps: decide again on the card itself.
  const final = open === card ? decision : decideCollect({ ...rules, type: open.type, goal: open.goal, step: open.step },
    { current: open.current, status: open.status, lastCollectedAt }, now);
  if (final.kind !== 'apply') {
    return json({ status: 'cooldown', retryAt: new Date(Date.now() + rules.cooldownMinutes * 60_000).toISOString(), remainingMinutes: rules.cooldownMinutes, businessName: business.name } satisfies CollectResponse);
  }

  const write = { p_card_id: open.id, p_expected_version: open.version, p_current: final.current, p_status: final.status, p_amount: final.added, p_business_id: business.id, p_staff_pin_id: staffPinId };
  let applied: boolean;
  if (tap) {
    // The tag's counter moves in the same transaction as the stamp, and only upwards.
    const { data, error } = await db.rpc('apply_nfc_collect', { ...write, p_tag_id: tap.tagId, p_counter: tap.counter });
    if (error) return json({ error: 'write' }, 500);
    if (data === 'stale') {
      await db.rpc('register_nfc_rejection', { p_tag_id: tap.tagId, p_user: user.id, p_counter: tap.counter, p_reason: 'stale' });
      return json({ status: 'nfc_replayed' } satisfies CollectResponse);
    }
    applied = data === 'ok';
  } else {
    const { data, error } = await db.rpc('apply_collect', { ...write, p_qr_code_id: qrId, p_source: 'qr' });
    if (error) return json({ error: 'write' }, 500);
    applied = !!data;
  }
  if (!applied) {
    // Another scan landed between the read and the write: it took the slot, so this one is in cooldown.
    return json({ status: 'cooldown', retryAt: new Date(Date.now() + rules.cooldownMinutes * 60_000).toISOString(), remainingMinutes: rules.cooldownMinutes, businessName: business.name } satisfies CollectResponse);
  }

  const info: CollectedCard = {
    cardId: open.id,
    businessId: business.id,
    businessName: business.name,
    programName: program.name,
    type: open.type,
    goal: open.goal,
    current: final.current,
    reward: open.reward,
  };
  // A full card: the stamp this PIN just wrote is the confirmation for taking the reward right away. A tap
  // without a PIN confirms nothing: the reward then needs the PIN as always.
  let confirmation: string | undefined;
  if (final.completed && staffPinId) {
    const { data: ev } = await db.from('stamp_events').select('id')
      .eq('card_id', open.id).eq('user_id', user.id).eq('staff_pin_id', staffPinId)
      .order('created_at', { ascending: false }).limit(1).maybeSingle();
    confirmation = ev?.id;
  }
  return json({ status: 'ok', ...info, added: final.added, completed: final.completed, confirmation } satisfies CollectResponse);
});
